 void OnDestroy(){if(restorePath)DungeonSaveStore.editorTestPath=previousPath;}
 IEnumerator Run(){var d=UnityEngine.Object.FindAnyObjectByType<DungeonPrototype>();var runtime=d.GetComponent<DungeonDecorationRuntime>();previousPath=DungeonSaveStore.editorTestPath;restorePath=true;DungeonSaveStore.editorTestPath="Tests/DecorationMainFixture.json";var p=DungeonDecorationPlanner.Build(d.mapSettings!=null?d.mapSettings:DungeonMapSettings.Current).FirstOrDefault(e=>e.prefabId.StartsWith("room."));Vector2Int pose=p!=null?p.cell-DungeonDecorationPlanner.Directions[p.heading]*2:new Vector2Int(7,25);int heading=p!=null?p.heading:0;var map=d.mapSettings!=null?d.mapSettings:DungeonMapSettings.Current;if(!map.IsFloor(pose))pose=p.cell-DungeonDecorationPlanner.Directions[p.heading];d.PrepareDecorationPreview(pose,heading);bool wasEnabled=d.enabled;d.enabled=false;
 var rows=new List<string>{"decorations,frames,fps,cpu_playerloop_ms,gpu_ms,draw_calls,setpass,gc_bytes_per_frame"};foreach(bool active in new[]{false,true}){runtime.generatedRoot.gameObject.SetActive(active);for(int i=0;i<30;i++)yield return null;var cpu=UnityEngine.Profiling.Recorder.Get("PlayerLoop");cpu.enabled=true;var gc=ProfilerRecorder.StartNew(ProfilerCategory.Memory,"GC Allocated In Frame");var ft=new FrameTiming[1];double elapsed=0,cp=0,gpu=0,calls=0,passes=0,alloc=0;int gpucount=0;const int count=180;for(int i=0;i<count;i++){yield return null;elapsed+=Time.unscaledDeltaTime;cp+=cpu.elapsedNanoseconds/1000000.0;calls+=UnityStats.drawCalls;passes+=UnityStats.setPassCalls;alloc+=gc.Valid?gc.LastValue:0;FrameTimingManager.CaptureFrameTimings();if(FrameTimingManager.GetLatestTimings(1,ft)>0&&ft[0].gpuFrameTime>0){gpu+=ft[0].gpuFrameTime;gpucount++;}}rows.Add((active?runtime.generatedRoot.childCount:0)+","+count+","+(count/elapsed).ToString("F2",CultureInfo.InvariantCulture)+","+(cp/count).ToString("F3",CultureInfo.InvariantCulture)+","+(gpucount>0?(gpu/gpucount).ToString("F3",CultureInfo.InvariantCulture):"unavailable")+","+(calls/count).ToString("F2",CultureInfo.InvariantCulture)+","+(passes/count).ToString("F2",CultureInfo.InvariantCulture)+","+(alloc/count).ToString("F0",CultureInfo.InvariantCulture));gc.Dispose();}
 runtime.generatedRoot.gameObject.SetActive(true);d.enabled=wasEnabled;var verification=new List<string>{"PASS Main decoration count "+runtime.generatedRoot.childCount,"PASS Collider count "+runtime.generatedRoot.GetComponentsInChildren<Collider>().Length,"PASS Added light count "+runtime.generatedRoot.GetComponentsInChildren<Light>().Length,"PASS Navigation rows unchanged "+(string.Join("\n",d.MapRows)==string.Join("\n",map.rows)),"PASS Unique planned IDs "+DungeonDecorationPlanner.Build(map).Select(e=>e.id).Distinct().Count(),"PASS Valid placements "+DungeonDecorationPlanner.Build(map).All(e=>DungeonDecorationPlanner.InvalidReason(map,e,map.decorations.Catalog.Find(e.prefabId))==null)};File.WriteAllLines("Tests/DecorationMainResults.txt",verification);File.WriteAllLines("Tests/DecorationPerformance.csv",rows);Summary=string.Join("\n",rows.ToArray());Finished=true;DungeonSaveStore.editorTestPath=previousPath;restorePath=false;Destroy(gameObject);
